rule malware_basic_detection {
    meta:
        description = "Advanced malware detection patterns"
        author = "Orbital Station"
        reference = "Advanced malware indicators"
        version = "2.0"
        last_modified = "2025-08-02"

    strings:
        // PE header - must be present for executable analysis
        $mz = { 4D 5A }

        // Suspicious command combinations (not just tool names)
        $malicious_combo_1 = "cmd.exe /c echo" nocase
        $malicious_combo_2 = "powershell.exe -enc" nocase
        $malicious_combo_3 = "powershell.exe -nop -w hidden" nocase
        $malicious_combo_4 = "rundll32.exe javascript:" nocase
        $malicious_combo_5 = "regsvr32.exe /s /u /i:" nocase
        $malicious_combo_6 = "mshta.exe javascript:" nocase
        $malicious_combo_7 = "certutil.exe -decode" nocase
        $malicious_combo_8 = "bitsadmin.exe /transfer" nocase

        // Encoded payloads - long base64 strings
        $encoded_payload = /[A-Za-z0-9+\/]{200,}={0,2}/
        $ps_frombase64 = "FromBase64String" nocase

        // Suspicious PowerShell obfuscation
        $ps_obfusc_1 = "-EncodedCommand" nocase
        $ps_obfusc_2 = "IEX(" nocase
        $ps_obfusc_3 = "Invoke-Expression" nocase
        $ps_download = "DownloadString" nocase

        // Registry persistence (specific suspicious modifications)
        $reg_persistence = /REG\s+ADD\s+HK[CLM]U\\Software\\Microsoft\\Windows\\CurrentVersion\\Run/ nocase

        // Anti-analysis API calls in suspicious context
        $inject_api_1 = "VirtualAllocEx" nocase
        $inject_api_2 = "WriteProcessMemory" nocase
        $inject_api_3 = "CreateRemoteThread" nocase
        $inject_api_4 = "SetThreadContext" nocase

        // Known malware tools
        $known_tool_1 = "mimikatz" nocase
        $known_tool_2 = "sekurlsa::logonpasswords" nocase
        $known_tool_3 = "lsadump::sam" nocase

        // Exclude legitimate system files by path context in strings
        $legit_path_1 = "C:\\Windows\\System32\\" nocase
        $legit_path_2 = "C:\\Windows\\SysWOW64\\" nocase
        $legit_path_3 = "Microsoft Corporation" nocase
        $legit_path_4 = "Windows NT" nocase

    condition:
        // Executable file with suspicious patterns
        $mz at 0 and
        filesize < 50MB and
        (
            // Multiple malicious command patterns
            (2 of ($malicious_combo_*)) or
            // Encoded PowerShell with obfuscation
            ($encoded_payload and 1 of ($ps_obfusc_*)) or
            // Process injection techniques
            (3 of ($inject_api_*)) or
            // Known malware tools
            (1 of ($known_tool_*)) or
            // Registry persistence with suspicious commands
            ($reg_persistence and 1 of ($malicious_combo_*))
        ) and
        // Exclude legitimate Windows system files
        not (2 of ($legit_path_*))
}

